<script setup>import {ref,onMounted} from 'vue';import {api} from '../services/api';import ProductCard from '../components/ProductCard.vue';const categories=ref([]),products=ref([]);onMounted(async()=>{categories.value=(await api.categories()).data;products.value=(await api.products({limit:8,sort:'featured'})).data});</script>
<template><section class="hero"><div><span class="eyebrow">NEW ARRIVAL</span><h1>Engineered for<br><em>Ultimate Performance.</em></h1><p>Discover the next generation of premium computing and precision electronics.</p><div class="actions"><router-link class="btn primary" to="/shop">Shop Now</router-link><a class="btn ghost" href="#categories">View Categories</a></div></div><div class="hero-art"><div class="orb"></div><div class="hero-device">VORA</div></div></section><section class="trust"><div><b>Fast Delivery</b><span>Next day available</span></div><div><b>Secure Payment</b><span>256-bit encryption</span></div><div><b>2-Year Warranty</b><span>On major electronics</span></div><div><b>Authentic Goods</b><span>100% genuine products</span></div></section><section id="categories" class="section"><div class="section-head"><div><span class="eyebrow">SHOP BY</span><h2>Categories</h2></div><router-link to="/shop">View All</router-link></div><div class="category-grid"><router-link v-for="c in categories" :key="c.id" class="category-card" :to="`/shop?category=${c.slug}`"><div class="category-art">{{c.name.slice(0,1)}}</div><div><h3>{{c.name}}</h3><p>{{c.description}}</p><span>Explore →</span></div></router-link></div></section><section class="section pale"><div class="section-head"><div><span class="eyebrow">CURATED</span><h2>High Performance Models</h2></div><router-link to="/shop">View All</router-link></div><div class="product-grid"><ProductCard v-for="p in products" :key="p.id" :product="p"/></div></section></template>
